SOURCE_INPUTS={'table': {'bytes': 30478, 'sha256': 'b4880f9c24dda10b566fa215c394295b6522a8ad448486918c591826480c09d8', 'compressed': ''}, 'saw': {'bytes': 17679, 'sha256': 'beba24d1853793d08f4217f53782c39c5b64b220497644bda7ac1618b96e845f', 'compressed': ''}, 'roller': {'bytes': 10732, 'sha256': '0ac23306f294df4989cd3a77d7b26d7bec9279fbe4a91bf96c300d5c481e1853', 'compressed': ''}, 'vacuum': {'bytes': 15798, 'sha256': 'a67a3d3e2b329516d9cf1a2af0f40dce9d1c37576d9355f03e32372184df2eab', 'compressed': ''}}
